import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.B3-dzFNu.js";const u=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":1794019245000}'),i={name:"roadmap.md"};function s(o,e,l,d,p,c){return t(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>Redline&#39;s goal is one review engine for local changes, forges and editors. This page separates available capabilities from planned integrations. Tracking issues contain the remaining work and acceptance criteria; they do not promise release dates.</p><h2 id="available-today" tabindex="-1">Available today <a class="header-anchor" href="#available-today" aria-label="Permalink to &quot;Available today&quot;">​</a></h2><ul><li>Local Git reviews of branches, commits and staged or unstaged changes. <a href="https://github.com/dragoscirjan/redline/issues/178" target="_blank" rel="noreferrer">CLI milestone #178</a>.</li><li>A versioned stdio JSON-RPC protocol for progress, cancellation and results. <a href="https://github.com/dragoscirjan/redline/issues/179" target="_blank" rel="noreferrer">Protocol milestone #179</a>.</li><li>GitHub Actions reviews, JSON/Markdown artifacts and optional publication of file reviews and a managed summary.</li><li>An image that runs Redline with Node, Bun, Python, Pi, OpenCode and the requested MCP packages installed. <a href="https://github.com/dragoscirjan/redline/issues/203" target="_blank" rel="noreferrer">Docker milestone #203</a>.</li></ul><p>The <a href="/projects/redline/docker-workers">Docker guide</a> explains usage and limits. Docker is started externally; Redline does not orchestrate containers. Image builds follow a successful new npm publication and use the same version tag. The npm CLI remains available without Docker.</p><h2 id="next-integration-work" tabindex="-1">Next integration work <a class="header-anchor" href="#next-integration-work" aria-label="Permalink to &quot;Next integration work&quot;">​</a></h2><ul><li><a href="https://github.com/dragoscirjan/redline/issues/180" target="_blank" rel="noreferrer">GitHub adapter over the shared engine #180</a>. Consolidate GitHub metadata and publication behind the shared application. Existing GitHub reviews are already available.</li><li><a href="https://github.com/dragoscirjan/redline/issues/181" target="_blank" rel="noreferrer">Forgejo and Gitea #181</a>. Share compatible API behavior and provide separately tested workflow templates.</li><li><a href="https://github.com/dragoscirjan/redline/issues/209" target="_blank" rel="noreferrer">Read-only MCP analysis #209</a>. Expose approved analysis tools to the review model. Installed server packages alone do not enable model tool access.</li></ul><h2 id="further-integration-targets" tabindex="-1">Further integration targets <a class="header-anchor" href="#further-integration-targets" aria-label="Permalink to &quot;Further integration targets&quot;">​</a></h2><p>These integrations are planned, not available capabilities:</p><table tabindex="0"><thead><tr><th>Integration</th><th>Goal</th></tr></thead><tbody><tr><td><a href="https://github.com/dragoscirjan/redline/issues/182" target="_blank" rel="noreferrer">VS Code and VSCodium #182</a></td><td>A thin JSON-RPC client published to Visual Studio Marketplace and Open VSX.</td></tr><tr><td><a href="https://github.com/dragoscirjan/redline/issues/183" target="_blank" rel="noreferrer">GitLab #183</a></td><td>GitLab.com and self-managed merge requests, with a maintained CI entrypoint.</td></tr><tr><td><a href="https://github.com/dragoscirjan/redline/issues/184" target="_blank" rel="noreferrer">Jujutsu #184</a></td><td>Native changes, revisions, bookmarks and workspaces, without reducing them to Git branch semantics.</td></tr><tr><td><a href="https://github.com/dragoscirjan/redline/issues/185" target="_blank" rel="noreferrer">Bitbucket Cloud #185</a></td><td>Pull request publication and Pipelines integration. Data Center remains deferred.</td></tr><tr><td><a href="https://github.com/dragoscirjan/redline/issues/186" target="_blank" rel="noreferrer">Mercurial #186</a></td><td>Native changesets, bookmarks, revision ranges and working-directory changes, without a Git mirror.</td></tr><tr><td><a href="https://github.com/dragoscirjan/redline/issues/187" target="_blank" rel="noreferrer">Zed #187</a></td><td>A thin JSON-RPC client that reports unsupported editor capabilities explicitly.</td></tr></tbody></table><h2 id="how-the-integrations-fit" tabindex="-1">How the integrations fit <a class="header-anchor" href="#how-the-integrations-fit" aria-label="Permalink to &quot;How the integrations fit&quot;">​</a></h2><p>Revision sources capture a change, forge adapters handle pull-request metadata and publication, and editor clients display progress and findings. These integrations share review policy, model execution, evidence validation and synthesis rather than implementing their own review engines.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Git CLI (#178)</span></span>
<span class="line"><span>├── JSON-RPC protocol (#179)</span></span>
<span class="line"><span>│   ├── VS Code / VSCodium (#182)</span></span>
<span class="line"><span>│   └── Zed (#187)</span></span>
<span class="line"><span>├── Redline Docker image (#203)</span></span>
<span class="line"><span>│   └── GitHub adapter (#180)</span></span>
<span class="line"><span>│       ├── Forgejo / Gitea (#181)</span></span>
<span class="line"><span>│       ├── GitLab (#183)</span></span>
<span class="line"><span>│       └── Bitbucket Cloud (#185)</span></span>
<span class="line"><span>├── Jujutsu adapter (#184)</span></span>
<span class="line"><span>└── Mercurial adapter (#186)</span></span></code></pre></div><p>Repository content remains data and is never executed during review. Podman is not a supported container engine. Managed local model runtimes and malicious-host protection are future work; Docker does not protect against its host administrator or kernel. See the <a href="/projects/redline/portable-architecture">architecture reference</a> for implementation boundaries.</p>`,14)])])}const g=a(i,[["render",s]]);export{u as __pageData,g as default};
